// Code Node - Validar Mensagem de Feedback
const message = $json.message;

// Verifica se tem mensagem de texto
if (!message || !message.text) {
  return { is_feedback: false };
}

const chatId = message.chat.id;
const userId = message.from.id;
const text = message.text;

// Ignora comandos
if (text.startsWith('/')) {
  return { is_feedback: false };
}

return {
  is_feedback: true,
  chat_id: chatId,
  user_id: userId,
  feedback_text: text,
  received_at: new Date().toISOString()
};

// Code Node - Estruturar Feedback (MIGRADO PARA NOVAS TABELAS)
const feedbackData = $('VALIDAR FEEDBACK').item.json;
const supabaseData = $('BUSCAR SESSAO ATIVA').item.json;

const sessions = Array.isArray(supabaseData) ? supabaseData : [supabaseData];

if (!sessions[0]) {
  throw new Error("Sessao nao encontrada no array");
}

const session = sessions[0];

return {
  post_update: {
    post_id: session.post_id,
    review_notes: feedbackData.feedback_text,
    status: 'needs_revision'
  },
  session_update: {
    session_id: session.session_id,
    status: 'completed',
    feedback_text: feedbackData.feedback_text,
    completed_at: new Date().toISOString()
  },
  telegram_confirm: {
    chat_id: feedbackData.chat_id || session.chat_id,
    text: `Feedback Recebido! Post sera revisado e reenviado.`,
    parse_mode: "Markdown"
  }
};

// Code Node - Extrair Message ID da Resposta do Telegram

const telegramResponse = $json;

if (!telegramResponse.ok || !telegramResponse.result) {
  throw new Error('Resposta do Telegram invalida: ' + JSON.stringify(telegramResponse));
}

const messageId = telegramResponse.result.message_id;
const draftId = $('PREPARAR TELEGRAM REVISADO').item.json.draft_id;

if (!draftId) {
  throw new Error('draft_id nao encontrado no node anterior');
}

const sentAt = new Date().toISOString();

return {
  post_id: draftId,
  telegram_message_id: messageId,
  review_started_at: sentAt
};

// Code Node - Preparar Post HTML REVISADO + Payload Telegram
const draft = $json;

if (!draft || !draft.id) {
  throw new Error('Post revisado nao possui dados validos');
}

const currentNumber = draft.review_order || 1;
const totalPosts = draft.total_in_session || 1;
const chatId = "8375309778";

let tierEmoji, tierLabel, tierColor;
switch(draft.tier) {
  case 'TIER_1':
    tierEmoji = '🔴';
    tierLabel = 'CRITICO - Revisao Urgente';
    tierColor = '#dc3545';
    break;
  case 'TIER_2':
    tierEmoji = '🟡';
    tierLabel = 'Normal - Revisao Regular';
    tierColor = '#ffc107';
    break;
  case 'TIER_3':
    tierEmoji = '🟢';
    tierLabel = 'Baixa Prioridade';
    tierColor = '#28a745';
    break;
  default:
    tierEmoji = '⚪';
    tierLabel = 'Sem Classificacao';
    tierColor = '#6c757d';
}

const createdDate = draft.created_at 
  ? new Date(draft.created_at).toLocaleDateString('pt-BR', {
      day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit'
    })
  : 'Data nao disponivel';

const originalDate = draft.original_date
  ? new Date(draft.original_date).toLocaleDateString('pt-BR')
  : null;

const categories = Array.isArray(draft.categories) 
  ? draft.categories.join(', ') 
  : (draft.categories || 'Sem categorias');

const postContent = draft.content_html || draft.content_markdown || 'Conteudo nao disponivel';

const htmlContent = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${draft.title || 'Post para Revisao'}</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.6; color: #333; background: #f5f5f5; padding: 16px; }
    .container { max-width: 800px; margin: 0 auto; background: white; border-radius: 12px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); overflow: hidden; }
    .revision-banner { background: #7c3aed; color: white; padding: 12px 20px; text-align: center; font-weight: 600; }
    .header { background: ${tierColor}; color: white; padding: 20px; }
    .header-badge { display: inline-block; background: rgba(255,255,255,0.2); padding: 4px 12px; border-radius: 20px; font-size: 14px; margin-bottom: 12px; }
    .header h1 { font-size: 22px; font-weight: 600; line-height: 1.3; }
    .meta-section { background: #f8f9fa; padding: 16px 20px; border-bottom: 1px solid #e9ecef; }
    .meta-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }
    .meta-item { font-size: 14px; }
    .meta-label { color: #666; font-size: 12px; text-transform: uppercase; }
    .meta-value { font-weight: 500; color: #333; }
    .categories { padding: 12px 20px; background: #fff; border-bottom: 1px solid #e9ecef; }
    .category-tag { display: inline-block; background: #e9ecef; color: #495057; padding: 4px 10px; border-radius: 4px; font-size: 13px; margin: 2px 4px 2px 0; }
    .content { padding: 24px 20px; }
    .content-label { font-size: 12px; text-transform: uppercase; color: #666; margin-bottom: 16px; font-weight: 600; }
    .content-body { font-size: 16px; line-height: 1.8; }
    .footer { background: #f8f9fa; padding: 16px 20px; font-size: 12px; color: #666; text-align: center; border-top: 1px solid #e9ecef; }
    .footer-id { font-family: monospace; background: #e9ecef; padding: 2px 8px; border-radius: 4px; }
  </style>
</head>
<body>
  <div class="container">
    <div class="revision-banner">🔄 VERSAO REVISADA - Confira as alteracoes</div>
    <div class="header">
      <div class="header-badge">${tierEmoji} ${tierLabel}</div>
      <h1>${draft.title || 'Titulo nao disponivel'}</h1>
    </div>
    <div class="meta-section">
      <div class="meta-grid">
        <div class="meta-item"><div class="meta-label">Palavras</div><div class="meta-value">${draft.word_count || 0}</div></div>
        <div class="meta-item"><div class="meta-label">Tempo de Leitura</div><div class="meta-value">${draft.reading_time_minutes || 1} min</div></div>
        <div class="meta-item"><div class="meta-label">Data Original</div><div class="meta-value">${originalDate || createdDate}</div></div>
      </div>
    </div>
    <div class="categories">
      <span class="meta-label">Categorias: </span>
      ${(Array.isArray(draft.categories) ? draft.categories : [categories]).map(cat => `<span class="category-tag">${cat}</span>`).join('')}
    </div>
    <div class="content">
      <div class="content-label">📄 Conteudo Completo</div>
      <div class="content-body">${postContent}</div>
    </div>
    <div class="footer">
      Post ID: <span class="footer-id">${draft.id || 'N/A'}</span>
    </div>
  </div>
</body>
</html>`;

const caption = `🔄 *REVISADO - POST ${currentNumber}/${totalPosts}*  |  ${tierEmoji} *${draft.tier || 'N/A'}*\n\n*${draft.title || 'Sem titulo'}*\n\n📊 ${draft.word_count || 0} palavras  •  ⏱ ${draft.reading_time_minutes || 1} min\n📁 ${categories}\n\n💡 _Confira as alteracoes no arquivo HTML_`;

const inlineKeyboard = [
  [
    { text: '✅ Aprovar Revisao', callback_data: `approve_${draft.id}` },
    { text: '📅 Agendar', callback_data: `schedule_${draft.id}` }
  ],
  [
    { text: '✏️ Editar Novamente', callback_data: `edit_${draft.id}` },
    { text: '❌ Rejeitar', callback_data: `reject_${draft.id}` }
  ],
  [
    { text: '⏭️ Pular', callback_data: `skip_${draft.id}` }
  ]
];

const fileName = `post_REVISADO_${draft.tier || 'draft'}_${(draft.id || 'unknown').substring(0, 8)}.html`;
const binaryData = Buffer.from(htmlContent, 'utf-8');

return {
  json: {
    chat_id: chatId,
    caption: caption,
    parse_mode: "Markdown",
    reply_markup: JSON.stringify({ inline_keyboard: inlineKeyboard }),
    draft_id: draft.id,
    draft_title: draft.title,
    file_name: fileName
  },
  binary: {
    document: {
      data: binaryData.toString('base64'),
      mimeType: 'text/html',
      fileName: fileName
    }
  }
};

// Preparar dados para o WF5 REVISION PROCESSOR
const processedData = $('PROCESSAR FEEDBACK').item.json;

return {
  post_id: processedData.post_update.post_id
};
